CREATE TABLE IF NOT EXISTS event_outbox(event_id VARCHAR(36) PRIMARY KEY,routing_key VARCHAR(100) NOT NULL,payload TEXT NOT NULL,created_at TIMESTAMP NOT NULL,published_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS consumed_events(event_id VARCHAR(36) PRIMARY KEY);
CREATE TABLE IF NOT EXISTS fd_statements(statement_id BIGINT AUTO_INCREMENT PRIMARY KEY,fd_account_no VARCHAR(20) NOT NULL,customer_id VARCHAR(20) NOT NULL,currency VARCHAR(3) NOT NULL,statement_date DATE NOT NULL,opening_balance DECIMAL(18,2) NOT NULL,interest_accrued DECIMAL(18,6) NOT NULL,interest_credited DECIMAL(18,2) NOT NULL,interest_paid DECIMAL(18,2) NOT NULL,closing_balance DECIMAL(18,2) NOT NULL,outstanding_interest DECIMAL(18,6) NOT NULL,last_occurred_at VARCHAR(40) NOT NULL,CONSTRAINT uk_statement_account_date UNIQUE(fd_account_no,statement_date));
